  3	final class IntArrayHeap {
  4	
  5	    private final int[] values;
  6	    private final int size;
  7	
  8	    private IntArrayHeap(int[] values) {
  9	        this.values = requireValues(values);
 10	        this.size = values.length;
 11	    }
 12	
 13	    static IntArrayHeap wrap(int[] values) {
 14	        return new IntArrayHeap(values);
 15	    }
 16	
 17	    static IntArrayHeap copyOf(int[] values) {
 18	        int[] copiedValues = Arrays.copyOf(requireValues(values), values.length);
 19	        return new IntArrayHeap(copiedValues);
 20	    }
 21	
 22	    IntArrayHeap buildMaxHeap() {
 23	        if (size < 2) {
 24	            return this;
 25	        }
 26	
 27	        for (int parentIndex = lastParentIndex(); parentIndex >= 0; parentIndex--) {
 28	            siftDown(parentIndex);
 29	        }
 30	
 31	        return this;
 32	    }
 33	
 34	    boolean isMaxHeap() {
 35	        for (int parentIndex = 0; parentIndex <= lastParentIndex(); parentIndex++) {
 36	            if (hasGreaterChild(parentIndex, leftChildIndex(parentIndex))) {
 37	                return false;
 38	            }
 39	
 40	            if (hasGreaterChild(parentIndex, rightChildIndex(parentIndex))) {
 41	                return false;
 42	            }
 43	        }
 44	
 45	        return true;
 46	    }
 47	
 48	    HeapBuildResult analyze() {
 49	        IntArrayHeap inputSnapshot = copy();
 50	        IntArrayHeap heapSnapshot = copy().buildMaxHeap();
 51	
 52	        return HeapBuildResult.of(
 53	                inputSnapshot.toArray(),
 54	                heapSnapshot.toArray(),
 55	                heapSnapshot.isMaxHeap());
 56	    }
 57	
 58	    int[] toArray() {
 59	        return values;
 60	    }
 61	
 62	    private IntArrayHeap copy() {
 63	        return new IntArrayHeap(Arrays.copyOf(values, size));
 64	    }
 65	
 66	    private void siftDown(int parentIndex) {
 67	        int currentIndex = parentIndex;
 68	
 69	        while (true) {
 70	            int largestIndex = currentIndex;
 71	            largestIndex = largerIndex(largestIndex, leftChildIndex(currentIndex));
 72	            largestIndex = largerIndex(largestIndex, rightChildIndex(currentIndex));
 73	
 74	            if (largestIndex == currentIndex) {
 75	                return;
 76	            }
 77	
 78	            swap(currentIndex, largestIndex);
 79	            currentIndex = largestIndex;
 80	        }
 81	    }
 82	
 83	    private boolean hasGreaterChild(int parentIndex, int childIndex) {
 84	        return childIndex < size && values[parentIndex] < values[childIndex];
 85	    }
 86	
 87	    private int largerIndex(int currentLargestIndex, int candidateIndex) {
 88	        if (candidateIndex < size && values[candidateIndex] > values[currentLargestIndex]) {
 89	            return candidateIndex;
 90	        }
 91	
 92	        return currentLargestIndex;
 93	    }
 94	
 95	    private int lastParentIndex() {
 96	        return (size / 2) - 1;
 97	    }
 98	
 99	    private int leftChildIndex(int parentIndex) {
100	        return (2 * parentIndex) + 1;
101	    }
102	
103	    private int rightChildIndex(int parentIndex) {
104	        return (2 * parentIndex) + 2;
105	    }
106	
107	    private void swap(int firstIndex, int secondIndex) {
108	        int temp = values[firstIndex];
109	        values[firstIndex] = values[secondIndex];
110	        values[secondIndex] = temp;
111	    }
112	
113	    private static int[] requireValues(int[] values) {
114	        if (values == null) {
115	            throw new IllegalArgumentException("values must not be null");
116	        }
117	
118	        return values;
119	    }
